/**
 * Entry point for the reusable "draft log entry" workflow (Requirements #1-3, #8).
 * Invoked on every push to a linked project repo: diffs against the last-synced
 * commit, redacts anything that looks like a secret (Requirement #17), sends the
 * diff + current docs to Claude, and commits the drafted log entry into
 * `projects/<project-name>/log/` in the caller's vault repo (Requirement #29).
 * No approval step.
 *
 * Also mirrors the project's own docs/PRODUCT.md (if it has one) into
 * `projects/<project-name>/product.md`, so the local chat server can answer
 * questions about intent/decisions/requirements without a GitHub API call.
 */
export declare function logEntryPath(projectName: string, commitSha: string): string;
export declare function draftLogEntry(): Promise<void>;
